class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        n = len(source)
        m = len(pattern)
        target_set = set(targetIndices)

        # Precompute indices for each character in pattern
        # We store them in a list for each character
        # To ensure we iterate in decreasing order, we sort them
        pattern_indices = {}
        for k, char in enumerate(pattern):
            if char not in pattern_indices:
                pattern_indices[char] = []
            pattern_indices[char].append(k)
        for char in pattern_indices:
            pattern_indices[char].sort(reverse=True)

        # dp[k] stores the minimum number of indices from targetIndices 
        # needed to match the prefix of pattern of length k.
        dp = [float('inf')] * (m + 1)
        dp[0] = 0

        for i, char in enumerate(source):
            if char in pattern_indices:
                for k in pattern_indices[char]:
                    cost = 1 if i in target_set else 0
                    if dp[k] != float('inf'):
                        if dp[k+1] > dp[k] + cost:
                            dp[k+1] = dp[k] + cost

        return len(targetIndices) - dp[m]

from typing import List

class Solution:
    def shiftDistance(self, s: str, t: str, nextCost: List[int], previousCost: List[int]) -> int:
        # Dictionary to cache the minimum cost for each pair of characters (u, v)
        # where u is the index of the character in s and v is the index of the character in t
        memo = {}

        total_shift_distance = 0
        n = len(s)

        for i in range(n):
            u = ord(s[i]) - ord('a')
            v = ord(t[i]) - ord('a')

            # If the cost for this pair has not been computed yet, compute it now
            if (u, v) not in memo:
                forward_cost = 0
                if u != v:
                    curr = u
                    while curr != v:
                        forward_cost += nextCost[curr]
                        curr = (curr + 1) % 26

                backward_cost = 0
                if u != v:
                    curr = u
                    while curr != v:
                        backward_cost += previousCost[curr]
                        curr = (curr - 1) % 26

                memo[(u, v)] = min(forward_cost, backward_cost)

            total_shift_distance += memo[(u, v)]

        return total_shift_distance
